import React, { useEffect, useState, useRef } from "react";
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../axiosService/ApiCall";
import { ToastContainer, toast } from "react-toastify";
import { useNavigate } from "react-router-dom";
import { MdDownloadForOffline } from "react-icons/md";
import { IoMdClose } from "react-icons/io";
import { Modal, Button, Spinner } from "react-bootstrap";
import { RiDeleteBin6Line } from "react-icons/ri";
import { MdRefresh } from "react-icons/md";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import { FaCalendarAlt } from "react-icons/fa";
import { set } from "date-fns";
import { number } from "yup";
import axios from "axios";
import { decryptData } from "../Auth/SecurityCrypto";
import Papa from "papaparse";
import { saveAs } from "file-saver";

function Userlist() {
  const [userList, setUserList] = useState([]);
  // console.log("userList", userList);

  const [businessList, setBussinessList] = useState([]);
  const [historyLoading, setHistoryLoading] = useState(true);
  //console.log("businessData",businessList )
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [currentBusinessPage, setCurrentBusinessPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [totalBussPages, setTotalBussPages] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(15);
  const [rowsPerPagetwo, setRowsPerPagetwo] = useState(15);
  const [showModal, setShowModal] = useState(false);
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [selectedRow, setSelectedRow] = useState(null);
  const [type, setType] = useState("");
  const [isLoading, setisLoading] = useState(false);
  const [isLoading1, setisLoading1] = useState(false);
  const [isLoadingActiveStatus, setisLoadingActiveStatus] = useState(false);
  // my code
  // ...................user state states.........................
  const [userSearchQuery, setUserSearchQuery] = useState("");
  //console.log("userSearchQuery", userSearchQuery);
  const [userAccountStatus, setUserAccountStatus] = useState("");
  const [userFromDate, setUserFromDate] = useState("");
  const [userToDate, setUserToDate] = useState("");
  // ...................user  states closed ...........................

  // ...................................Business state states.....................
  const [businessSearchQuery, setBusinessSearchQuery] = useState("");
  const [businessAccountStatus, setBusinessAccountStatus] = useState("");
  const [businessFromDate, setBusinessFromDate] = useState("");
  const [businessToDate, setBusinessToDate] = useState("");
  // ...................................Business state finished.....................
  // ..................................User Activation Status start & indivdual status.....................
  const [userKycStatus, setUserKycstatus] = useState("");
  const [userindividualStatus, setIndividualstatus] = useState("");

  // console.log("isLoading--", isLoading);

  const [status, setStatus] = useState("");
  const [activeTab, setActiveTab] = useState("user");
  //console.log("activeTab", activeTab);

  const [totalItems, setTotalItems] = useState(0);
  const [bussTotalItems, setBussTotalItems] = useState(0);
  //console.log("bussTotalItems",bussTotalItems);

  const [account_status, setAccount_Status] = useState("");

  const Navigate = useNavigate();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [showCalendar, setShowCalendar] = useState(false);
  const [selectedId, setSelectedId] = useState(null);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [viewData, setViewData] = useState(0);
  const [editAccountpage, setEditAccountpage] = useState(0);
  // console.log("editAccountpage", editAccountpage);

  // console.log("editAccountpage", editAccountpage);

  // ...................Date range picker states.........................
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const [registerType, setRegisterType] = useState("");
  const [deleteType, setDeleteType] = useState("");
  const [tfaFilter, setTfaFilter] = useState("");
  // console.log("tfaFilter", tfaFilter);

  // console.log("registerType", registerType);

  const calendarRef = useRef(null);
  // subadmin edit access control ..........
  const [adminType, setAdminType] = useState("");
  const [UserListEditData, setUserListEditData] = useState("");

  // subadmin edit access control ..........

  // .................view & edit permission fetch response...................
  const vieweditres = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const vieweditres = await makeApiRequest(params);
      // console.log("vieweditres", vieweditres);
      if (vieweditres.status) {
        const response = vieweditres.data;
        setEditAccountpage(response.adminPermissions.accounts.Edit);
        setAdminType(response.admin_type);
        // setUserListEditData(response.adminPermissions)
      }
    } catch (error) {
      //toast("Something Went Wrong...");
    }
  };
  useEffect(() => {
    vieweditres();
  }, [editAccountpage]);

  const getUserData = async (
    page = 1,
    search = "",
    account_status = "",
    fromDate = "",
    toDate = "",
    kycStatus = userKycStatus,
    individualStatus = userindividualStatus,
    register_Type = registerType,
    delete_Type = deleteType
  ) => {
    try {
      setisLoading(true);
      let queryParams = new URLSearchParams({
        search: search || "",
        account_status,
        fromDate,
        toDate,
        kyc_Status: kycStatus || "",
        individualStatus: individualStatus || "",
        register_Type,
        delete_Type,
        page: page,
        limitUser: rowsPerPage,
        limitBusiness: rowsPerPagetwo,
      }).toString();
      let params = {
        url: `userDetails?${queryParams}`,
        method: "GET",
      };

      const response = await makeApiRequest(params);
      // console.log("getUser", response);

      if (response.status === true) {
        const {
          data,
          businessData,
          totalPages,
          totalBusinessPages,
          totalItems,
          totalBusinessItems,
        } = response;
        // console.log("res", data);
        setUserList(data);
        setBussinessList(businessData);
        setHistoryLoading(false);
        setTotalPages(totalPages);
        setTotalBussPages(totalBusinessPages);
        setTotalItems(totalItems);
        setBussTotalItems(totalBusinessItems);
        // setType
      } else {
        setUserList([]);
        setisLoading(false);
        setHistoryLoading(false);
      }
    } catch (error) {
      console.log("UserListPageErr", error);
      //toast.error("Something Wrong");
      setHistoryLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab == "user") {
      getUserData(
        currentPage,
        userSearchQuery,
        userAccountStatus,
        userFromDate,
        userToDate,
        userKycStatus,
        userindividualStatus,
        registerType,
        deleteType,
        currentPage
      );
    } else if (activeTab == "business") {
      getUserData(
        currentBusinessPage,
        businessSearchQuery,
        businessAccountStatus,
        businessFromDate,
        businessToDate,
        currentBusinessPage
      );
    }
  }, [
    currentPage,
    currentBusinessPage,
    userSearchQuery,
    businessSearchQuery,
    userAccountStatus,
    businessAccountStatus,
    userFromDate,
    userToDate,
    userKycStatus,
    userindividualStatus,
    businessFromDate,
    businessToDate,
    rowsPerPage,
    rowsPerPagetwo,
    activeTab,
    registerType,
    deleteType,
  ]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);
  // .......................handleClearFilters ...............

  const handleClearFilters = async () => {
    handleResert();
    if (activeTab === "user") {
      setUserSearchQuery("");
      setUserFromDate("");
      setUserToDate("");
      setUserAccountStatus("");
      setUserKycstatus("");
      setRegisterType("");
      setDeleteType("");
    } else if (activeTab === "business") {
      setBusinessSearchQuery("");
      setBusinessFromDate("");
      setBusinessToDate("");
      setBusinessAccountStatus("");
    }
    setAccount_Status("");
    setIndividualstatus("");
    setSearchQuery("");
    setType("");
    setStatus("");
    setFromDate("");
    setToDate("");

    setIsRefreshing(true);
    setTfaFilter("");

    const start = Date.now();

    if (activeTab === "user") {
      await getUserData(1, "", userAccountStatus, "", "", status);
    } else if (activeTab === "business") {
      await getUserData(1, "", businessAccountStatus, "", "", status);
    }

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      await new Promise((resolve) => setTimeout(resolve, 500 - elapsed));
    }

    setIsRefreshing(false);
  };

  const handleUserPageChange = (newPage) => {
    if (activeTab === "user") setCurrentPage(newPage);
  };

  const handleBusinessPageChange = (newPage) => {
    if (activeTab === "business") setCurrentBusinessPage(newPage);
  };

  // Handle search input change
  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
    handleResert();
  };

  const handleClick = (id, actionType) => {
    // console.log("actionType", actionType);

    if (editAccountpage == 0 && adminType == "SubAdmin") {
      // toast.warning(
      //   "Access Denied: You are not allowed to edit individual details."
      // );
      // return;
      let msg = "";
      if (actionType == "1") {
        // toast.warning("Access Denied: You are not allowed to edit deactivate details.");
        msg = "Access Denied: You are not allowed to edit deactivate details.";
      } else if (actionType == "2") {
        msg = "Access Denied: You are not allowed to edit delete details.";
      } else if (actionType == "3") {
        msg = "Access Denied: You are not allowed to edit activate details.";
      }
      // console.log("msg", msg);

      toast.warning(msg);
      return;
    } else {
      setSelectedId(id);
    }
    setShowModal(true);
  };

  const handleClose = () => {
    setShowModal(false);
    setType("");
    setTimeout(() => {
      window.location.reload();
    }, 1000);
  };
  // .........................user active status code  ..........................
  async function Confirmation() {
    try {
      // console.log("work--");
      setisLoadingActiveStatus(true);
      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;

      let datas = {
        userListID: selectedId,
        type: type,
        ip: lastloginIpAddress,
      };

      if (type === "Delete") {
        datas.deleteBy = "Admin";
      }

      let params = {
        url: `UserListAction`,
        method: "POST",
        data: datas,
      };
      const responseKycDelete = await makeApiRequest(params);
      // console.log("responseKycDelete", responseKycDelete);
      if (responseKycDelete.status == true) {
        //alert("User " + type + " successfully");
        toast.success(responseKycDelete.message);
        getUserData(
          currentPage,
          searchQuery,
          userAccountStatus,
          businessAccountStatus
        );
        setisLoadingActiveStatus(false);
        setTimeout(() => {
          window.location.reload();
        }, 1000);
        setShowModal(false);
        setSelectedId(null);
        setType("");
      }
    } catch (err) {
      console.log("error", err);
      setisLoading1(false);
    }
  }
  // .........................user active status code finish  ..........................

  // const dateFormat = (date) => {
  //   try {
  //     const orgDate = new Date(date);
  //     const options = {
  //       year: "numeric",
  //       month: "short",
  //       day: "numeric",
  //     };
  //     return orgDate.toLocaleDateString("en-GB", options);
  //   } catch (e) {
  //     return "Invalid Date";
  //   }
  // };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };
  // ............admin side handle click.................
  const adminDisableClick = async (userId) => {
    try {
      if (editAccountpage == 0 && adminType == "SubAdmin") {
        toast.warning("You don't have permission to disable user 2FA");
        return;
      }
      // console.log("Clicked Row ID:", userId);
      const address = await axios.get("https://api.ipify.org/?format=json");
      // console.log("address", address);

      const lastloginIpAddress = address.data.ip;

      let params = {
        url: `2fa-adminDisable`,
        method: "POST",

        data: { userId, lastloginIpAddress },
        headers: {
