                      style={{ position: "relative", width: "max-content" }}
                    >
                      <div
                        onClick={() => {
                          if (activeTab === "user") {
                            setShowCalendar(!showCalendar);
                            setRowsPerPage(rowsPerPage);
                            setCurrentPage(1);
                          }
                        }}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          padding: "6px",
                          border: "1px solid var(--color-1)",
                          borderRadius: "5px",
                          cursor: "pointer",
                          backgroundColor: "#fff",
                          fontSize: "14px",
                        }}
                      >
                        <span>
                          {userFromDate && userToDate
                            ? `${dateFormat(userFromDate)} - ${dateFormat(
                              userToDate
                            )}`
                            : "select the date"}
                        </span>
                        <FaCalendarAlt
                          style={{ color: "#555" }}
                          className="ms-1"
                        />
                      </div>

                      {/* Date range picker (shows when input is clicked) */}
                      {showCalendar && (
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: -80,
                            zIndex: 1000,
                            background: "#fff",
                            boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                            borderRadius: "5px",
                          }}
                        >
                          <DateRange
                            editableDateInputs={true}
                            onChange={handleDateChange}
                            moveRangeOnFirstSelection={false}
                            ranges={range}
                            locale={enUS}
                            rangeColors={["#58f9b0"]}
                          />
                        </div>
                      )}
                    </div>
                  </div>
                )}
                <div className="mb-3">
                  <label htmlFor="tfaStatus" className="form-label">
                    TFA Status
                  </label>
                  <select
                    className="form-select search-bar"
                    id="tfaStatus"
                    value={tfaFilter}
                    onChange={(e) => {
                      const value = e.target.value;
                      handleResert();
                      setTfaFilter(value);
                      handleTfaFilter(value);
                    }}
                  >
                    <option value="">All Status</option>
                    <option value="Disabled">Disabled</option>
                  </select>
                </div>
                {/* Download CSV Button */}
                <div className="mb-2 me-2">
                  <button
                    type="button"
                    className="form-label custom-nav-button-1 active cursor-pointer mt-6"
                    onClick={handleDownloadUserlist}
                  // disabled={editAccountpage == 0 && adminType == "SubAdmin"}
                  >
                    <i className="bi bi-download me-1 text-white"></i> Download
                    CSV
                  </button>
                </div>

                <div className="mb-2">
                  <button
                    type="button"
                    className="form-label custom-nav-button-1 active cursor-pointer"
                    onClick={handleClearFilters}
                    disabled={isRefreshing} // optional, disable button while refreshing
                  >
                    <MdRefresh
                      style={{ fontSize: "24px" }}
                      className={isRefreshing ? "rotate-icon" : ""}
                    />
                  </button>
                </div>
              </div>

              <div className="tab-content" id="pills-tabContent">
                <div
                  className="tab-pane fade show active"
                  id="pills-home"
                  role="tabpanel"
                  aria-labelledby="pills-home-tab"
                  tabindex="0"
                >
                  {isVisible == true ? (
                    <div className="custom-heading-scroll d-flex justify-content-between">
                      <p className="mb-0">
                        The table below can be scrolled horizontally, if needed.
                      </p>
                      <div onClick={handleClose1} style={{ cursor: "pointer" }}>
                        <IoMdClose />
                      </div>
                    </div>
                  ) : (
                    ""
                  )}

                  <div className="liquidity-table-1">
                    <DataTable
                      key={rowsPerPage}
                      columns={columnsone}
                      data={getFilteredUserList()}
                      theme="solarized"
                      defaultSortAsc={true}
                      pagination
                      paginationServer
                      paginationTotalRows={totalItems}
                      onChangePage={handleUserPageChange}
                      paginationResetDefaultPage={resetPaginationToggle}
                      paginationPerPage={rowsPerPage}
                      paginationRowsPerPageOptions={[15, 25, 100]}
                      onChangeRowsPerPage={(newPerPage) => {
                        setRowsPerPage(newPerPage);
                        // getUserData(page, searchQuery, status, activeStatus,newPerPage);
                      }}
                      highlightOnHover
                      dense
                      // noDataComponent={
                      //   isLoading ? (
                      //     <div className="text-center py-2">
                      //       <Spinner animation="border" />
                      //     </div>
                      //   ) : (
                      //     <div className="text-center py-2">
                      //       <span>No data found</span>
                      //     </div>
                      //   )
                      // }
                      noDataComponent={
                        <div className="text-center py-2">
                          <span>There is no records to display</span>
                        </div>
                      }
                      progressPending={historyLoading}
                      progressComponent={
                        <div
                          className="py-4 w-100"
                          style={{ marginLeft: "45vw" }}
                        >
                          <Spinner animation="border" />
                        </div>
                      }
                    />
                  </div>
                </div>
                <div
                  className="tab-pane fade"
                  id="pills-profile"
                  role="tabpanel"
                  aria-labelledby="pills-profile-tab"
                  tabindex="0"
                >
                  {isVisible == true ? (
                    <div className="custom-heading-scroll d-flex justify-content-between">
                      <p className="mb-0">
                        The table below can be scrolled horizontally, if needed.
                      </p>
                      <div onClick={handleClose1} style={{ cursor: "pointer" }}>
                        <IoMdClose />
                      </div>
                    </div>
                  ) : (
                    ""
                  )}

                  <div className="liquidity-table-1">
                    <DataTable
                      columns={bussColumns}
                      data={businessList}
                      theme="solarized"
                      defaultSortAsc={true}
                      pagination
                      paginationServer
                      paginationTotalRows={bussTotalItems}
                      onChangePage={handleBusinessPageChange}
                      paginationPerPage={rowsPerPagetwo}
                      paginationRowsPerPageOptions={[15, 25, 100]}
                      onChangeRowsPerPage={(newPerPage, page) => {
                        setRowsPerPagetwo(newPerPage);
                        // getUserData(page, searchQuery, status, activeStatus,newPerPage);
                      }}
                      highlightOnHover
                      dense
                      noDataComponent={
                        <div className="text-center py-2">
                          <span>There is no records to display</span>
                        </div>
                      }
                      progressPending={historyLoading}
                      progressComponent={
                        <div
                          className="py-4 w-100"
                          style={{ marginLeft: "45vw" }}
                        >
                          <Spinner animation="border" />
                        </div>
                      }
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Userlist;
